import SwiftUI
import SwiftData

struct EntryForm: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; let kind: String; @State private var title = ""; @State private var category = "Other"; @State private var amount = ""; var body: some View { NavigationStack { Form { TextField("Title", text: $title); TextField("Category", text: $category); TextField("Amount", text: $amount).keyboardType(.decimalPad) }.navigationTitle(kind == "income" ? "Add income" : "Add expense").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Save") { if let value = Double(amount), !title.isEmpty { context.insert(ExpenseEntry(kind: kind, title: title, category: category, amount: value)); dismiss() } }.disabled(Double(amount) == nil || title.isEmpty) } } } } }
struct SettingsView: View { let entries: [ExpenseEntry]; var body: some View { NavigationStack { List { Section("AURELIS") { LabeledContent("Currency", value: "₹ INR"); LabeledContent("Storage", value: "On device"); LabeledContent("Entries", value: "\(entries.count)") } Section { Text("Your data stays on this device. Export and cloud sync can be added as native features.").font(.footnote).foregroundStyle(.secondary) } }.navigationTitle("Vault") } } }
